const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the administrative boundary for Quebec, Canada.
  const quebecAdmin = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.eq('ADM1_NAME', 'Quebec'));
  const geometry = quebecAdmin.geometry();

  // Define the time period for the analysis.
  const startDate = '2023-01-01';
  const endDate = '2023-12-31';

  // 2. Data Acquisition & Check
  // Use the MODIS Burned Area product.
  const collection = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterBounds(geometry)
    .filterDate(startDate, endDate);

  // Check if the collection is empty.
  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log('No MODIS MCD64A1 images found for 2023 in the region.');
    console.log('C1');
    return;
  }
  console.log(`Initial MODIS image count for 2023: ${collectionSize}`);

  // 3. Processing
  // Create a composite of all burned areas throughout the year.
  // A pixel is considered burned if its 'BurnDate' is greater than 0 on any day of the year.
  const annualBurn = collection.select('BurnDate').max();
  const burnedMask = annualBurn.gt(0); // Create a binary mask of burned areas.

  // Use ee.Image.pixelArea() to get the area of each pixel in square meters.
  const areaImage = ee.Image.pixelArea().updateMask(burnedMask);

  // 4. Calculation
  // Sum the area of all burned pixels within the Quebec geometry.
  // Using a larger scale (500m is native for MODIS) to ensure the calculation completes.
  const areaStats = areaImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 500,
    maxPixels: 1e10
  });

  const burnedAreaSqM = areaStats.get('area');

  // Check for calculation failure.
  if (burnedAreaSqM.getInfo() === null) {
    console.log('Calculation failed: could not retrieve burned area statistics.');
    console.log('C3');
    return;
  }

  // Convert area from square meters to hectares (1 hectare = 10,000 sq meters).
  const burnedAreaHectares = ee.Number(burnedAreaSqM).divide(10000).getInfo();
  const targetHectares = 0.8 * 1000000; // 0.8 million hectares

  // 5. Validation & Final Answer
  console.log(`Target Burn Area (Ha): ${targetHectares.toLocaleString()}`);
  console.log(`Calculated Burn Area (Ha): ${Math.round(burnedAreaHectares).toLocaleString()}`);

  if (burnedAreaHectares === 0) {
      console.log('No burned pixels were detected in the final analysis.');
  }

  if (burnedAreaHectares > targetHectares) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`An error occurred: ${e}`);
    console.log('D');
  }
}

initEE();
